package intervals

import (
	"reflect"
	"testing"
)

func TestMergeBasic(t *testing.T) {
	got := Merge([][2]int{{1, 3}, {2, 6}, {8, 10}, {15, 18}})
	want := [][2]int{{1, 6}, {8, 10}, {15, 18}}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

func TestMergeTouching(t *testing.T) {
	got := Merge([][2]int{{1, 4}, {4, 5}})
	want := [][2]int{{1, 5}}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

func TestMergeUnsorted(t *testing.T) {
	got := Merge([][2]int{{6, 8}, {1, 3}, {2, 5}})
	want := [][2]int{{1, 5}, {6, 8}}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

func TestMergeNoOverlap(t *testing.T) {
	got := Merge([][2]int{{1, 2}, {3, 4}})
	want := [][2]int{{1, 2}, {3, 4}}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}
